def solve(g, nbfill=True, ties='first'):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    # noise: colors all of whose comps are singletons and count>1
    def allsingle(c):
        s=comps(g,c); return all(len(s)==1 for s in s) and len(s)>1
    noise=[c for c in cnt if c!=bg and allsingle(c)]
    if len(noise)!=1: raise Exception('noise ambig',noise,[cnt[c] for c in noise])
    rare=noise[0]
    lab=[[g[i][j] for j in range(W)] for i in range(H)]
    q=deque()
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and g[i][j]!=rare:
                q.append((i,j))
    while q:
        y,x=q.popleft()
        d=[[None]*(W) for _ in range(H)]
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]==rare and lab[ny][nx]==rare:
                    d[ny][nx]=(abs(ny-y)+abs(nx-x), abs(ny-y)+abs(nx-x)-1, ny,nx)
                    q.append((ny,nx))
    # now assign: shortest path distance
    dis=[[10**6]*W for _ in range(H)]; par={}
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and g[i][j]!=rare: dis[i][j]=0
    q=deque([(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg and g[i][j]!=rare])
    while q:
        y,x=q.popleft()
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                ny,nx=y+dy,x+dx
                if 0<=ny<H and 0<=nx<W and g[ny][nx]==rare and dis[ny][nx]>dis[y][x]+1:
                    dis[ny][nx]=dis[y][x]+1; q.append((ny,nx))
    for i in range(H):
        for j in range(W):
            if g[i][j]==rare:
                lab[i][j]=[v for v in (dis[i][j], None)][0]
    # assign colors by nearest solid (8-neighborhood, tie -> smallest color? try variants)
    res=[[bg]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]==rare:
                best=None
                for dy in(-1,0,1):
                    for dx in(-1,0,1):
                        y,x=i+dy,j+dx
                        if 0<=y<H and 0<=x<W and g[y][x]!=bg and g[y][x]!=rare:
                            c=g[y][x]; d=abs(y-i)+abs(x-j)
                            cand=(d,c)
                            if best is None or cand<best: best=cand
                res[i][j]=best[1] if best else bg
    keep=[j for j in range(W) if any(res[i][j]!=bg for i in range(H))]
    return [[res[i][j] for j in keep] for i in range(H)], dis
