    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                c=g[i][j]; st=[(i,j)]; cl=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in {(a,b) for a,b in cl}: continue
                    cl.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
