def comps3(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; cells=set()
                while st:
                    y,x=st.pop(); cells.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append((c,cells))
    return out

def try_rule(g, absorb_mode, order_key, move_pref):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cs=comps3(g,bg)
    multi=[(c,set(cells)) for c,cells in cs if len(cells)>1]
    singles=[(c,list(cells)[0]) for c,cells in cs if len(cells)==1]
    ents=[{'c':c,'cells':set()} for c,_ in multi]
    for idx,(c,cells) in enumerate(multi): ents[idx]['cells']=cells
    if absorb_mode=='adj':
        for c,p in singles:
            hosts=[e for e in ents if any(abs(p[0]-y)+abs(p[1]-x)<=1 for y,x in e['cells'])]
            if hosts: host=min(hosts,key=lambda e:min(abs(p[0]-y)+abs(p[1]-x) for y,x in e['cells'])); host['cells'].add(p)
            else:
                best=min(ents,key=lambda e:min(abs(p[0]-y)+abs(p[1]-x) for y,x in e['cells']))
                best['cells'].add(p)
    elif absorb_mode=='nearest_any':
        for c,p in singles:
            best=min(ents,key=lambda e:min(abs(p[0]-y)+abs(p[1]-x) for y,x in e['cells']))
            best['cells'].add(p)
    occ=frozenset()
    moved=True
    while moved:
        moved=False
        entlist=list(ents)
        for i,e in enumerate(entlist):
            cur=e['cells']
            others=occ-{cell for j,e2 in enumerate(ents) if j!=i for cell in e2['cells']}
            pref=move_pref
            steps=0
            while steps<2:
                cand=None
                for dy,dx in pref:
                    nxt={(r+dy,c+dx) for r,c in cur}
                    if all(0<=r<h and 0<=c<w and (r,c) not in others for r,c in nxt):
                        cand=(dy,dx); break
                if cand is None: break
                cur={ (r+cand[0],c+cand[1]) for r,c in cur }; others|=cur; moved=True; steps+=1
            e['cells']=cur
        occ=frozenset({cell for e in ents for cell in e['cells']})
    out=[[bg]*w for _ in range(h)]
    for e in ents:
        for r,c in e['cells']: out[r][c]=e['c']
    w2=w-1
    while w2>0 and all(out[r][w2]==bg for r in range(h)): w2-=1
    return [row[:w2+1] for row in out]

